# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step5B_sample_specific_domain_relation.R
# 5A Step 5B: frozen modules versus sample-specific 1A domains
local({
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(pheatmap)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225';OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225');S<-file.path(OUT,'step5B_sample_specific_domain_relation');dir.create(S,recursive=TRUE,showWarnings=FALSE)
sa<-readRDS(file.path(OUT,'step4_module_activity_spatial_organization','pixel_module_activity_scores.rds'));meta<-as.data.table(sa$pixel_metadata);allscore<-sa$scores;mods<-colnames(allscore)
mo<-readRDS(file.path(OUT,'step3_modules','MSI_consensus_modules.rds'));reps<-as.data.table(mo$representatives)[module!='grey',.(feature_index,module)]
D1<-file.path(BASE,'intratumor_spatial_heterogeneity_10samples_part1_consensus_tuned225');fq<-fread(file.path(D1,'within_sample_discovery_validation_feature_qc.csv'))
lab0<-as.data.table(readRDS(file.path(D1,'tumor_pixels_within_sample_consensus_domains.rds')))[,.(original_pixel_row,sample_id,raw_tic,detected_peak_count,alignment_nmatch,within_domain=as.character(consensus_domain),within_stable=stable_core_pixel,consensus_probability,consensus_entropy,spatial_organization_type)]
lab<-merge(meta,lab0,by=c('original_pixel_row','sample_id'),all.x=TRUE,sort=FALSE);lab<-lab[match(meta$original_pixel_row,original_pixel_row)];stopifnot(all(lab$original_pixel_row==meta$original_pixel_row))
val_union<-sort(unique(fq[feature_role=='validation' & passed_strict_filter==TRUE & matrix_feature_index%in%reps$feature_index,matrix_feature_index]));X0<-readRDS(file.path(BASE,'pixel_by_feature_matrix_aligned_logCPM.rds'));X<-as.matrix(X0[meta$original_pixel_row,val_union,drop=FALSE]);rm(X0);gc()
safez<-function(v){s<-sd(v,na.rm=TRUE);if(!is.finite(s)||s<1e-10)return(rep(0,length(v)));as.numeric((v-mean(v,na.rm=TRUE))/s)}
eta2<-function(v,g,keep=rep(TRUE,length(v))){ok<-keep&is.finite(v)&!is.na(g);v<-v[ok];g<-g[ok];if(length(v)<10||uniqueN(g)<2)return(NA_real_);t<-sum((v-mean(v))^2);if(t<=0)return(NA_real_);1-sum(vapply(split(v,g),function(x)sum((x-mean(x))^2),numeric(1)))/t}
valscore<-matrix(NA_real_,nrow(meta),length(mods),dimnames=list(NULL,mods));support<-list()
for(si in sort(unique(meta$sample_id))){ii<-which(meta$sample_id==si);vf<-fq[sample_id==si & feature_role=='validation' & passed_strict_filter==TRUE & matrix_feature_index%in%reps$feature_index,matrix_feature_index];jj<-match(vf,val_union);Y<-X[ii,jj,drop=FALSE];T<-cbind(1,safez(log1p(lab$raw_tic[ii])),safez(lab$detected_peak_count[ii]),safez(lab$alignment_nmatch[ii]));Z<-apply(qr.resid(qr(T),Y),2,safez);if(is.null(dim(Z)))Z<-matrix(Z,ncol=1);for(mm in mods){ff<-reps[module==mm & feature_index%in%vf,feature_index];kk<-match(ff,vf);if(length(kk)>=3)valscore[ii,mm]<-rowMeans(Z[,kk,drop=FALSE]);support[[length(support)+1L]]<-data.table(sample=si,module=mm,n_validation_features=length(kk))}}
support<-rbindlist(support);fwrite(support,file.path(S,'sample_specific_validation_feature_support.csv'));saveRDS(list(scores=valscore,support=support,definition='Per-sample module score uses only the independent-validation features withheld from that sample 1A domain discovery; module membership remains frozen.'),file.path(S,'sample_specific_validation_only_module_scores.rds'));rm(X);gc()
rows<-list();prof<-list();hotprof<-list()
for(si in sort(unique(lab$sample_id))){ii<-which(lab$sample_id==si);for(mm in mods){nv<-support[sample==si&module==mm,n_validation_features];v<-valscore[ii,mm];g<-lab$within_domain[ii];st<-lab$within_stable[ii];eall<-eta2(v,g);est<-eta2(v,g,st);if(length(nv)==0||nv<3){eall<-est<-NA_real_};vz<-safez(v);ok<-is.finite(vz)&!is.na(g);ds<-data.table(domain=g[ok],z=vz[ok],stable=st[ok])[,.(mean_z=mean(z),mean_z_stable=if(sum(stable)>=5)mean(z[stable]) else NA_real_,sd_z=sd(z),n_pixels=.N,n_stable=sum(stable)),by=domain];if(nrow(ds)){ds[,c('sample','module'):=list(si,mm)];prof[[length(prof)+1L]]<-ds};dom_hi<-if(nrow(ds))ds$domain[which.max(ds$mean_z)] else NA_character_;dom_lo<-if(nrow(ds))ds$domain[which.min(ds$mean_z)] else NA_character_;amp<-if(nrow(ds))diff(range(ds$mean_z)) else NA_real_;q80<-quantile(vz[ok],.8,na.rm=TRUE);hp<-data.table(domain=g[ok],hot=vz[ok]>=q80)[,.(n_pixels=.N,n_hot=sum(hot),hot_rate=mean(hot)),by=domain];if(nrow(hp)){hp[,hot_enrichment:=hot_rate/mean(vz[ok]>=q80)];hp[,hotspot_purity:=n_hot/sum(n_hot)];hp[,c('sample','module'):=list(si,mm)];hotprof[[length(hotprof)+1L]]<-hp};mxen<-if(nrow(hp))max(hp$hot_enrichment) else NA_real_;hdom<-if(nrow(hp))hp$domain[which.max(hp$hot_enrichment)] else NA_character_;pur<-if(nrow(hp))hp$hotspot_purity[which.max(hp$hot_enrichment)] else NA_real_;use<-if(is.finite(est))est else eall;cls<-if(!is.finite(use))'unsupported_lt3_validation_features' else if(use>=.25)'strong_domain_aligned' else if(use>=.10)'partial_domain_related' else 'trans_domain_program';rows[[length(rows)+1L]]<-data.table(sample=si,module=mm,n_validation_features=nv,eta2_validation_all=eall,eta2_validation_stable=est,domain_relation_class=cls,highest_activity_domain=dom_hi,lowest_activity_domain=dom_lo,domain_mean_z_range=amp,hotspot_enriched_domain=hdom,max_hotspot_enrichment=mxen,hotspot_purity_in_enriched_domain=pur)}}
res<-rbindlist(rows);prof<-rbindlist(prof);hotprof<-rbindlist(hotprof);fwrite(res,file.path(S,'sample_module_specific_domain_relations.csv'));fwrite(prof,file.path(S,'sample_domain_module_profiles_validation_only.csv'));fwrite(hotprof,file.path(S,'sample_domain_module_hotspot_enrichment_validation_only.csv'))
summ<-res[,.(median_sample_specific_eta2_validation=median(eta2_validation_stable,na.rm=TRUE),min_sample_specific_eta2_validation=min(eta2_validation_stable,na.rm=TRUE),max_sample_specific_eta2_validation=max(eta2_validation_stable,na.rm=TRUE),n_samples_evaluable=sum(is.finite(eta2_validation_stable)),n_samples_strong=sum(domain_relation_class=='strong_domain_aligned'),n_samples_partial=sum(domain_relation_class=='partial_domain_related'),n_samples_trans_domain=sum(domain_relation_class=='trans_domain_program')),by=module];summ[n_samples_evaluable==0,c('median_sample_specific_eta2_validation','min_sample_specific_eta2_validation','max_sample_specific_eta2_validation'):=NA_real_];setorder(summ,-median_sample_specific_eta2_validation);fwrite(summ,file.path(S,'module_sample_specific_domain_summary.csv'))
top_by_sample<-res[is.finite(eta2_validation_stable)][order(sample,-eta2_validation_stable),head(.SD,5),by=sample];fwrite(top_by_sample,file.path(S,'top5_domain_related_modules_per_sample.csv'))
top_by_domain<-prof[is.finite(mean_z_stable)][order(sample,domain,-mean_z_stable),head(.SD,3),by=.(sample,domain)];fwrite(top_by_domain,file.path(S,'top3_modules_per_sample_specific_domain.csv'))
pdf(file.path(S,'sample_specific_domain_module_relations.pdf'),width=12,height=8);hm<-dcast(res,sample~module,value.var='eta2_validation_stable');mat<-as.matrix(hm[,-1]);rownames(mat)<-hm$sample;pheatmap(mat,cluster_rows=FALSE,cluster_cols=FALSE,main='Frozen MSI modules vs sample-specific domains\nvalidation-only stable-core eta-squared',border_color=NA,na_col='grey90');p1<-ggplot(res[is.finite(eta2_validation_stable)],aes(x=reorder(module,eta2_validation_stable,FUN=median),y=eta2_validation_stable))+geom_boxplot(fill='#80B1D3',outlier.size=.7)+geom_hline(yintercept=c(.10,.25),linetype=c(3,2),color=c('grey40','#B2182B'))+coord_flip()+labs(x=NULL,y='Validation-only eta-squared (stable cores)',title='Sample-specific domain dependence of frozen modules')+theme_bw(base_size=11);print(p1);p2<-ggplot(res,aes(x=module,y=sample,fill=domain_relation_class))+geom_tile(color='white')+scale_fill_manual(values=c(strong_domain_aligned='#D73027',partial_domain_related='#FDAE61',trans_domain_program='#74ADD1',unsupported_lt3_validation_features='grey85'))+labs(x=NULL,y=NULL,fill=NULL,title='Per-sample relationship class (heuristic thresholds)')+theme_bw(base_size=11)+theme(axis.text.x=element_text(angle=45,hjust=1));print(p2);dev.off()
master<-fread(file.path(OUT,'MASTER_module_evidence_table.csv'));old<-intersect(names(master),setdiff(names(summ),'module'));if(length(old))master[,(old):=NULL];master<-merge(master,summ,by='module',all.x=TRUE,sort=FALSE);fwrite(master,file.path(OUT,'MASTER_module_evidence_table.csv'));saveRDS(master,file.path(OUT,'MASTER_module_evidence_table.rds'))
writeLines(c('Modules and their scores were frozen before 1A labels were read.','Primary sample-specific estimates use only features assigned to the independent-validation role in each sample 1A split; at least 3 frozen-module validation features are required.','Stable-core eta-squared is primary; all-pixel eta-squared, domain means, and top-20-percent hotspot enrichment are also reported.','D1/D2 labels are sample-specific and are not treated as homologous across tumors.','Relationship classes use descriptive thresholds: strong >=0.25, partial 0.10-0.25, trans-domain <0.10. They are interpretation aids, not hypothesis-test cutoffs.','No domain or LC-MS/MS field changes module detection, membership, ranking, or spatial metrics.'),file.path(S,'README.txt'));file.create(file.path(S,'STEP5B_COMPLETE.ok'));cat('STEP5B_COMPLETE\n');print(summ);cat('TOP_PER_SAMPLE\n');print(top_by_sample[,.(sample,module,eta2_validation_stable,n_validation_features,domain_relation_class)]);if(requireNamespace('rstudioapi',quietly=TRUE))rstudioapi::navigateToFile(file.path(S,'top5_domain_related_modules_per_sample.csv'))
})
